import { Check, ChevronDown, Search, SlidersHorizontal, Sparkles } from 'lucide-react'
import { useEffect, useMemo, useRef, useState } from 'react'
import type { AiRuntimeKind } from '@shared/ai-types'
import { runtimeUsesFreeformModel, runtimeUsesGrimoireProvider, type RuntimeSelectionContract } from '@shared/runtime-contract'

export type CherryProviderOption = { id: string; name: string; default_model: string; models: string[] }
export type CherryModelOption = { id: string; name?: string; capabilities?: string[]; contextWindow?: number; maxOutputTokens?: number }

function useOutsideClose(ref: React.RefObject<HTMLDivElement | null>, close: () => void) {
  useEffect(() => {
    const handler = (event: MouseEvent) => { if (ref.current && !ref.current.contains(event.target as Node)) close() }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [close, ref])
}

export function CherryProviderModelSelector({ providers, provider, catalogModels, model, runtime, contract, ready = false, onProviderChange, onModelChange }: { providers: CherryProviderOption[]; provider?: CherryProviderOption | null; catalogModels: CherryModelOption[]; model: string; runtime: AiRuntimeKind; contract?: RuntimeSelectionContract; ready?: boolean; onProviderChange: (id: string) => Promise<void>; onModelChange: (model: string) => Promise<void> }) {
  const [providerOpen, setProviderOpen] = useState(false)
  const [modelOpen, setModelOpen] = useState(false)
  const [query, setQuery] = useState('')
  const [capability, setCapability] = useState('')
  const providerRef = useRef<HTMLDivElement>(null)
  const modelRef = useRef<HTMLDivElement>(null)
  useOutsideClose(providerRef, () => setProviderOpen(false))
  useOutsideClose(modelRef, () => setModelOpen(false))

  const capabilities = useMemo(() => Array.from(new Set(catalogModels.flatMap(item => item.capabilities || []))).sort(), [catalogModels])
  const models = useMemo(() => {
    const merged = Array.from(new Map([...((provider?.models || []).map((id): CherryModelOption => ({ id }))), ...catalogModels].map(item => [item.id, item])).values())
    const normalized = query.trim().toLowerCase()
    return merged.filter(item => (!normalized || [item.id, item.name || '', ...(item.capabilities || [])].join(' ').toLowerCase().includes(normalized)) && (!capability || (item.capabilities || []).includes(capability)))
  }, [catalogModels, capability, provider?.models, query])
  const contractReady = ready && !!contract
  const localRuntime = contractReady && !runtimeUsesGrimoireProvider(contract)
  const freeformModel = contractReady && runtimeUsesFreeformModel(contract)
  const selectedModel = catalogModels.find(item => item.id === model) || models.find(item => item.id === model)

  return <div className="space-y-3 rounded-xl border border-[var(--color-border)] bg-[var(--color-bg-primary)] p-3 text-xs">
    <div className="flex items-center gap-2 text-[var(--color-text-secondary)]"><SlidersHorizontal size={14} /><span className="font-semibold">模型选择</span><span className="ml-auto rounded-full bg-[var(--color-bg-tertiary)] px-2 py-0.5 text-[10px]">{runtime}</span></div>{!contractReady && <div className="rounded-lg bg-[var(--color-bg-tertiary)] px-2 py-1 text-[10px] text-[var(--color-text-secondary)]">Runtime 状态加载中，Provider/Model 选择暂不可用</div>}
    <div ref={providerRef} className="relative"><span className="mb-1 block text-[var(--color-text-secondary)]">Provider</span><button type="button" disabled={!contractReady || localRuntime} onClick={() => setProviderOpen(value => !value)} className="flex w-full items-center gap-2 rounded-lg border border-[var(--color-border)] bg-[var(--color-bg-secondary)] px-3 py-2 text-left hover:border-[var(--color-accent)]/60 disabled:cursor-not-allowed disabled:opacity-60"><span className="min-w-0 flex-1 truncate text-[var(--color-text-primary)]">{provider?.name || '未配置 Provider'}</span><ChevronDown size={14} className="shrink-0 text-[var(--color-text-secondary)]" /></button>{providerOpen && <div className="absolute inset-x-0 top-full z-30 mt-1 max-h-56 overflow-auto rounded-xl border border-[var(--color-border-strong)] bg-[var(--color-bg-primary)] p-1 shadow-2xl"><button type="button" className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-xs hover:bg-[var(--color-bg-tertiary)]" onClick={() => { void onProviderChange(''); setProviderOpen(false) }}><span className="flex-1">未配置 Provider</span>{!provider && <Check size={14} className="text-[var(--color-accent-text)]" />}</button>{providers.map(item => <button type="button" key={item.id} className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-xs hover:bg-[var(--color-bg-tertiary)]" onClick={() => { void onProviderChange(item.id); setProviderOpen(false) }}><span className="min-w-0 flex-1 truncate"><span className="block text-[var(--color-text-primary)]">{item.name}</span><span className="block text-[10px] text-[var(--color-text-secondary)]">{item.models.length} 个模型 · 默认 {item.default_model || '未设置'}</span></span>{provider?.id === item.id && <Check size={14} className="text-[var(--color-accent-text)]" />}</button>)}</div>}{localRuntime && <span className="mt-1 block text-[10px] text-[var(--color-text-secondary)]">本地 Runtime 不需要 Provider</span>}</div>
    <div ref={modelRef} className="relative"><span className="mb-1 block text-[var(--color-text-secondary)]">Model</span>{freeformModel ? <input className="ui-field w-full" value={model} onChange={event => void onModelChange(event.target.value)} placeholder="输入 Runtime 模型名" /> : <><button type="button" disabled={!contractReady} onClick={() => setModelOpen(value => !value)} className="flex w-full items-center gap-2 rounded-lg border border-[var(--color-border)] bg-[var(--color-bg-secondary)] px-3 py-2 text-left hover:border-[var(--color-accent)]/60"><span className="min-w-0 flex-1 truncate text-[var(--color-text-primary)]">{selectedModel?.name || selectedModel?.id || model || '选择模型'}</span><ChevronDown size={14} className="shrink-0 text-[var(--color-text-secondary)]" /></button>{modelOpen && <div className="absolute inset-x-0 top-full z-30 mt-1 overflow-hidden rounded-xl border border-[var(--color-border-strong)] bg-[var(--color-bg-primary)] shadow-2xl"><div className="space-y-2 border-b border-[var(--color-border)] p-2"><label className="relative block"><Search size={13} className="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2 text-[var(--color-text-secondary)]" /><input autoFocus className="ui-field w-full pl-7 text-[11px]" value={query} onChange={event => setQuery(event.target.value)} placeholder="搜索模型、Provider 或能力" aria-label="搜索模型" /></label><div className="flex gap-1 overflow-x-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">{['', ...capabilities].slice(0, 12).map(item => <button type="button" key={item || 'all'} onClick={() => setCapability(item)} className={'shrink-0 rounded-full border px-2 py-1 text-[10px] ' + (capability === item ? 'border-[var(--color-accent)] bg-[var(--color-accent)]/15 text-[var(--color-accent-text)]' : 'border-[var(--color-border)] text-[var(--color-text-secondary)]')}>{item || '全部能力'}</button>)}</div></div><div className="max-h-64 overflow-auto p-1">{models.length === 0 ? <div className="p-4 text-center text-xs text-[var(--color-text-secondary)]">没有匹配的模型</div> : models.map(item => <button type="button" key={item.id} className="flex w-full items-start gap-2 rounded-lg px-3 py-2 text-left hover:bg-[var(--color-bg-tertiary)]" onClick={() => { void onModelChange(item.id); setModelOpen(false) }}><Sparkles size={14} className="mt-0.5 shrink-0 text-[var(--color-accent-text)]" /><span className="min-w-0 flex-1"><span className="block truncate text-xs text-[var(--color-text-primary)]">{item.name || item.id}</span><span className="mt-1 flex flex-wrap gap-1 text-[10px] text-[var(--color-text-secondary)]">{(item.capabilities || []).slice(0, 5).map(value => <span key={value} className="rounded bg-[var(--color-bg-tertiary)] px-1.5 py-0.5">{value}</span>)}{item.contextWindow ? <span className="rounded bg-[var(--color-bg-tertiary)] px-1.5 py-0.5">上下文 {item.contextWindow.toLocaleString()}</span> : null}</span></span>{item.id === model && <Check size={14} className="mt-0.5 shrink-0 text-[var(--color-accent-text)]" />}</button>)}</div></div>}</>}</div>
    {selectedModel && <div className="rounded-lg bg-[var(--color-bg-secondary)] p-2 text-[10px] text-[var(--color-text-secondary)]"><div className="font-medium text-[var(--color-text-primary)]">{selectedModel.name || selectedModel.id}</div><div className="mt-1 flex flex-wrap gap-1">{(selectedModel.capabilities || []).map(value => <span key={value} className="rounded bg-[var(--color-bg-tertiary)] px-1.5 py-0.5">{value}</span>)}{selectedModel.contextWindow ? <span className="rounded bg-[var(--color-bg-tertiary)] px-1.5 py-0.5">上下文 {selectedModel.contextWindow.toLocaleString()}</span> : null}</div></div>}
  </div>
}
